files.content:
.root {
  position: relative;
  display: grid;
  gap: 10px;
  color: var(--foreground);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-body);
  line-height: var(--leading-body);
}
.root *, .root *::before, .root *::after { box-sizing: border-box; }
.root[data-layout="grid"] { grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--min-column, 180px)), 1fr)); }
.root[data-layout="list"] { grid-template-columns: minmax(0, 1fr); gap: 8px; }

/* The one moving part: a ring that springs from card to card. It sits over the card border so the card itself never changes size. */
.ring {
  position: absolute;
  z-index: 1;
  top: 0;
  left: 0;
  border: 1.5px solid var(--control-on);
  border-radius: 20px;
  pointer-events: none;
}

.card {
  position: relative;
  display: grid;
  min-width: 0;
  align-items: start;
  gap: 4px 12px;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--surface);
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard);
}
.root[data-layout="grid"] .card { grid-template-areas: "body indicator" "meta meta"; grid-template-columns: minmax(0, 1fr) auto; align-content: start; }
.root[data-layout="list"] .card { grid-template-areas: "indicator body meta"; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; padding: 13px 16px 13px 14px; }
.card[data-checked] { background: color-mix(in oklch, var(--control-on) 4%, var(--surface)); }
.card[aria-disabled="true"] { background: var(--surface-muted); cursor: not-allowed; }
.card[aria-disabled="true"] :is(.label, .meta) { color: var(--text-muted); }

.indicator {
  display: grid;
  width: 18px;
  height: 18px;
  flex: none;
  place-items: center;
  grid-area: indicator;
  border: 1.5px solid var(--border-strong);
  border-radius: 50%;
  transition: border-color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard);
}
.root[data-layout="grid"] .indicator { margin-top: 1px; }
.card[data-checked] .indicator { border-color: var(--control-on); background: var(--control-on); }
.indicatorDot { width: 6px; height: 6px; border-radius: 50%; background: var(--control-glyph); }
.card[aria-disabled="true"] .indicator { border-color: var(--border); }

.body { display: grid; min-width: 0; gap: 2px; grid-area: body; }
.label { display: flex; min-width: 0; align-items: center; gap: 8px; font-weight: 500; }
.labelText { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.icon { display: grid; width: 18px; height: 18px; flex: none; place-items: center; color: var(--text-secondary); }
.icon > svg { width: 18px; height: 18px; }
.card[data-checked] .icon { color: var(--foreground); }
.description { color: var(--text-secondary); font-size: var(--text-xs); line-height: 1.45; text-wrap: pretty; }

.meta { grid-area: meta; color: var(--foreground); font-variant-numeric: tabular-nums; white-space: nowrap; }
.root[data-layout="grid"] .meta { margin-top: 10px; font-size: var(--text-lg); }
.root[data-layout="list"] .meta { font-weight: 500; }

@media (hover: hover) and (pointer: fine) {
  .card:not([data-checked]):not([aria-disabled="true"]):hover { border-color: var(--border-strong); }
}
.card:not([data-checked]):not([aria-disabled="true"]):active { background: var(--surface-muted); }
.card:focus-visible { outline: 2px solid var(--control-on); outline-offset: 2px; }
.card:focus-visible:not([data-checked]) { border-color: var(--border-strong); background: var(--surface-muted); }

@media (prefers-reduced-motion: reduce) {
  .card, .indicator { transition: none; }
}
